server <- function(input, output, session) {
  
  # ==========================================
  # Navigation Logic (INDEX)
  # ==========================================
  observeEvent(input$link_2_1, { updateNavbarPage(session, "main_nav", selected = "tab_2_1") })
  observeEvent(input$link_2_2, { updateNavbarPage(session, "main_nav", selected = "tab_2_2") })
