  observeEvent(input$link_6_2, { updateNavbarPage(session, "main_nav", selected = "tab_6_2") })
  observeEvent(input$link_7_1, { updateNavbarPage(session, "main_nav", selected = "tab_7_1") })
  observeEvent(input$link_7_2, { updateNavbarPage(session, "main_nav", selected = "tab_7_2") })
  observeEvent(input$link_8_2, { updateNavbarPage(session, "main_nav", selected = "tab_8_2") })
  observeEvent(input$link_8_3, { updateNavbarPage(session, "main_nav", selected = "tab_8_3") })
  observeEvent(input$link_9, { updateNavbarPage(session, "main_nav", selected = "tab_9") })
  observeEvent(input$link_10, { updateNavbarPage(session, "main_nav", selected = "tab_10") })
  observeEvent(input$link_11_4, { updateNavbarPage(session, "main_nav", selected = "tab_11_4") })
  observeEvent(input$link_12, { updateNavbarPage(session, "main_nav", selected = "tab_12") })
  observeEvent(input$link_13, { updateNavbarPage(session, "main_nav", selected = "tab_13") })
  observeEvent(input$link_es, { updateNavbarPage(session, "main_nav", selected = "tab_es") })
  observeEvent(input$link_ss, { updateNavbarPage(session, "main_nav", selected = "tab_ss") })
  
  # ==========================================
  # CHAPTER 2
