  data_reactive_21 <- reactive({ cleaned_input <- gsub("[,\\n]", " ", input$frequencies_21); split_input <- unlist(strsplit(trimws(cleaned_input), "\\s+")); frequencies <- as.numeric(split_input); frequencies <- frequencies[!is.na(frequencies)]; if (length(frequencies) == 0) return(NULL); classes <- as.character(1:length(frequencies)); df <- data.frame(Class = factor(classes, levels = classes), Frequency = frequencies); total_freq <- sum(df$Frequency, na.rm = TRUE); df <- df %>% mutate(`Cumulative Frequency` = cumsum(Frequency), `Relative Frequency` = Frequency / total_freq, `Relative Frequency %` = `Relative Frequency`, `Cumulative Relative Frequency` = cumsum(`Relative Frequency`), `Cumulative Relative Frequency %` = `Cumulative Relative Frequency`); return(df) })
  output$summary_table_21 <- renderDT({ df <- data_reactive_21(); if (is.null(df)) return(datatable(data.frame(Error="Please enter valid numeric frequencies."))); total_row <- data.frame(Class = "Total", Frequency = sum(df$Frequency), `Cumulative Frequency` = max(df$`Cumulative Frequency`), `Relative Frequency` = sum(df$`Relative Frequency`), `Relative Frequency %` = sum(df$`Relative Frequency %`), `Cumulative Relative Frequency` = 1.0, `Cumulative Relative Frequency %` = 1.0, check.names = FALSE); datatable(rbind(df, total_row), options = list(pageLength = 20, dom = 't')) %>% formatPercentage(c('Relative Frequency %', 'Cumulative Relative Frequency %'), 2) %>% formatRound(c('Relative Frequency', 'Cumulative Relative Frequency'), 4) })
