  output$paretoChart_21 <- renderPlot({ df <- data_reactive_21(); if(is.null(df)) return(NULL); ggplot(df, aes(x=Class, y=`Relative Frequency`, fill=Class)) + geom_bar(stat="identity", show.legend=FALSE) + scale_y_continuous(labels=scales::percent) + theme_minimal() + labs(title="Relative Frequency Bar Chart", x="Class", y="Relative Frequency (%)") })
