  data_reactive_22 <- reactive({ cleaned_input <- gsub("[,\\n]", " ", input$data_input_22); split_input <- unlist(strsplit(trimws(cleaned_input), "\\s+")); vals <- as.numeric(split_input); vals[!is.na(vals)] })
  output$stats_table_22 <- renderDT({ x <- data_reactive_22(); if (length(x) == 0) return(datatable(data.frame(Error="Please enter valid numeric data."))); mean_val <- mean(x); median_val <- median(x); mode_val <- get_mode(x); min_val <- min(x); max_val <- max(x); midrange <- (min_val + max_val) / 2; q1 <- unname(quantile(x, probs=0.25, type=6)); q2 <- unname(quantile(x, probs=0.50, type=6)); q3 <- unname(quantile(x, probs=0.75, type=6)); range_val <- max_val - min_val; var_val <- var(x); sd_val <- sd(x); cv_val <- sd_val / mean_val; iqr_val <- q3 - q1; semi_iqr <- iqr_val / 2; mid_quartile <- (q1 + q3) / 2; df <- data.frame(Measures = c("Mean (x-bar)", "Median (Me)", "Mode (Mo)", "Midrange (MR)", "Minimum (Min)", "Quartile 1 (Q1)", "Quartile 2 (Q2)", "Quartile 3 (Q3)", "Maximum (Max)", "Range (R)", "Variance (s2, Var)", "Standard Deviation (SD)", "Coefficient of Variation (CV)", "Interquartile Range (IQR)", "Semi-IQR", "Mid-Quartile"), Value = c(fmt(mean_val), fmt(median_val), mode_val, fmt(midrange), fmt(min_val), fmt(q1), fmt(q2), fmt(q3), fmt(max_val), fmt(range_val), fmt(var_val), fmt(sd_val), fmt(cv_val), fmt(iqr_val), fmt(semi_iqr), fmt(mid_quartile))); datatable(df, options = list(pageLength = 20, dom = 't', ordering = FALSE), rownames = FALSE) })
  output$boxplot_22 <- renderPlot({ x <- data_reactive_22(); if(length(x)==0) return(NULL); ggplot(data.frame(Values=x), aes(x="", y=Values)) + geom_boxplot(fill="lightblue", color="darkblue", outlier.color="red", outlier.size=3) + theme_minimal() + labs(title="Box Plot of Data Values", x="", y="Value") + theme(plot.title=element_text(hjust=0.5, size=16, face="bold")) })
  output$val_to_perc_table_22 <- renderDT({ x <- data_reactive_22(); val <- input$target_value_22; if(length(x)==0 || is.na(val)) return(NULL); num_less <- sum(x < val); total_count <- length(x); df <- data.frame(Metric = c("Target Value", "Number < Value", "Total Count", "Traditional Percentile", "Exclusive Percentile"), Result = c(as.character(val), as.character(num_less), as.character(total_count), sprintf("%.4f%%", (num_less/total_count)*100), sprintf("%.4f%%", ((num_less+1)/(total_count+1))*100))); datatable(df, options = list(dom = 't', ordering = FALSE, columnDefs = list(list(width = '200px', targets = 0))), rownames = FALSE) })
  output$perc_to_val_table_22 <- renderDT({ x <- sort(data_reactive_22()); p <- input$target_percentile_22; n <- length(x); if(n==0 || is.na(p)) return(NULL); locator <- (p / 100) * n; val_trad <- if(locator%%1==0) { if(locator==0) x[1] else if(locator==n) x[n] else (x[locator]+x[locator+1])/2 } else { x[ceiling(locator)] }; df <- data.frame(Metric = c("Target Percentile", "Total Count", "Locator", "Data Value (Traditional)", "Data Value (Exclusive)"), Result = c(as.character(p), as.character(n), as.character(locator), sprintf("%.4f", val_trad), sprintf("%.4f", unname(quantile(x, probs=p/100, type=6))))); datatable(df, options = list(dom = 't', ordering = FALSE, columnDefs = list(list(width = '200px', targets = 0))), rownames = FALSE) })
  
