  output$ch3_st_table_main <- renderDT({ a <- input$ch3_st_a; b <- input$ch3_st_b; c <- input$ch3_st_c; d <- input$ch3_st_d; tpr <- a / (a + c); tnr <- d / (b + d); if (!is.na(input$ch3_st_rate) && input$ch3_st_rate > 0) { prev <- input$ch3_st_rate / 100; ppv <- (tpr * prev) / ((tpr * prev) + ((1 - tnr) * (1 - prev))); npv <- (tnr * (1 - prev)) / ((tnr * (1 - prev)) + ((1 - tpr) * prev)) } else { ppv <- a / (a + b); npv <- d / (c + d) }; datatable(data.frame(Result=c("TPR", "TNR", "PPV", "NPV"), Definition=c("Sensitivity (True Positive Rate)", "Specificity (True Negative Rate)", "Precision (Positive Predictive Value)", "Negative Predictive Value"), Value=c(sprintf("%.4f%%", tpr*100), sprintf("%.4f%%", tnr*100), sprintf("%.4f%%", ppv*100), sprintf("%.4f%%", npv*100))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_st_table_others <- renderDT({ a <- input$ch3_st_a; b <- input$ch3_st_b; c <- input$ch3_st_c; d <- input$ch3_st_d; tpr <- a / (a + c); tnr <- d / (b + d); acc <- (a + d) / (a + b + c + d); inacc <- 1 - acc; f1 <- (2 * a) / (2 * a + b + c); prev <- (a + c) / (a + b + c + d); fnr <- c / (a + c); fpr <- b / (b + d); for_val <- c / (c + d); fdr <- b / (a + b); lr_pos <- tpr / fpr; lr_neg <- fnr / tnr; dor <- lr_pos / lr_neg; datatable(data.frame(Others=c("ACC", "INACC", "F1 Score", "PREV", "FNR", "FPR", "FOR", "FDR", "LR+", "LR-", "DOR"), Definition=c("Accuracy", "Inaccuracy", "Harmonic mean of precision", "Prevalence", "False Negative Rate (Miss Rate)", "False Positive Rate (Fall-Out Rate)", "False Omission Rate", "False Discovery Rate", "Positive Likelihood Ratio", "Negative Likelihood Ratio", "Diagnostic Odds Ratio"), Value=c(sprintf("%.4f%%", acc*100), sprintf("%.4f%%", inacc*100), sprintf("%.4f", f1), sprintf("%.4f%%", prev*100), sprintf("%.4f%%", fnr*100), sprintf("%.4f%%", fpr*100), sprintf("%.4f%%", for_val*100), sprintf("%.4f%%", fdr*100), sprintf("%.4f", lr_pos), sprintf("%.4f", lr_neg), sprintf("%.4f", dor))), options=list(pageLength=15, dom='t', ordering=F), rownames=F) })
  ch3_re_calc <- reactive({ a <- input$ch3_re_a; b <- input$ch3_re_b; c <- input$ch3_re_c; d <- input$ch3_re_d; n1 <- a + b; n2 <- c + d; p1 <- a / n1; p2 <- c / n2; arr <- p1 - p2; rr <- p1 / p2; nnt <- 1 / abs(arr); z_crit <- qnorm(1 - (1 - input$ch3_re_ci/100)/2); se_ln_rr <- sqrt(1/a + 1/c - 1/n1 - 1/n2); lcl <- rr * exp(-z_crit * se_ln_rr); ucl <- rr * exp(z_crit * se_ln_rr); z_score <- abs(log(rr) / se_ln_rr); p_val <- 2 * (1 - pnorm(z_score)); list(arr=arr, rr=rr, nnt=nnt, lcl=lcl, ucl=ucl, z=z_score, p=p_val, se=se_ln_rr) })
  output$ch3_re_table_main <- renderDT({ res <- ch3_re_calc(); datatable(data.frame(Result=c("Absolute Risk Reduction", "Relative Risk", "Number Needed to Treat", "SD{ln(RR)}"), Value=c(fmt(res$arr), fmt(res$rr), sprintf("%.0f", res$nnt), fmt(res$se))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_re_table_ci <- renderDT({ res <- ch3_re_calc(); datatable(data.frame(RR=fmt(res$rr), LCL=fmt(res$lcl), UCL=fmt(res$ucl)), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_re_table_z <- renderDT({ res <- ch3_re_calc(); datatable(data.frame(`z-score`=fmt(res$z), `p-value`=fmt(res$p), check.names=F), options=list(dom='t', ordering=F), rownames=F) })
  ch3_oe_calc <- reactive({ a <- input$ch3_oe_a; b <- input$ch3_oe_b; c <- input$ch3_oe_c; d <- input$ch3_oe_d; p_e <- a/(a+b); p_ne <- b/(a+b); oa <- b/a; of <- a/b; or_val <- (a/b)/(c/d); z_crit <- qnorm(1 - (1 - input$ch3_oe_ci/100)/2); se_ln_or <- sqrt(1/a + 1/b + 1/c + 1/d); lcl <- or_val * exp(-z_crit * se_ln_or); ucl <- or_val * exp(z_crit * se_ln_or); z_score <- abs(log(or_val) / se_ln_or); p_val <- 2 * (1 - pnorm(z_score)); list(p_e=p_e, p_ne=p_ne, oa=oa, of=of, or=or_val, lcl=lcl, ucl=ucl, z=z_score, p=p_val, se=se_ln_or) })
  output$ch3_oe_table_main <- renderDT({ res <- ch3_oe_calc(); datatable(data.frame(Result=c("P(Event for Group 1)", "P(NOT Event for Group 1)", "Actual Odds Against", "Actual Odds in Favor", "Odds Ratio", "SD{ln(OR)}"), Value=c(fmt(res$p_e), fmt(res$p_ne), fmt(res$oa), fmt(res$of), fmt(res$or), fmt(res$se))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_oe_table_ci <- renderDT({ res <- ch3_oe_calc(); datatable(data.frame(OR=fmt(res$or), LCL=fmt(res$lcl), UCL=fmt(res$ucl)), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_oe_table_z <- renderDT({ res <- ch3_oe_calc(); datatable(data.frame(`z-score`=fmt(res$z), `p-value`=fmt(res$p), check.names=F), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_pv1_table_calc <- renderDT({ lnlcl <- log(input$ch3_pv1_lcl); lnucl <- log(input$ch3_pv1_ucl); z <- qnorm(1 - (1 - input$ch3_pv1_ci/100)/2); se <- (lnucl - lnlcl) / (2 * z); b <- (lnlcl + lnucl) / 2; datatable(data.frame(Metric=c("lnLCL", "lnUCL", "z", "SE", "B"), Value=c(fmt(lnlcl), fmt(lnucl), fmt(z), fmt(se), fmt(b))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_pv1_table_est <- renderDT({ lnlcl <- log(input$ch3_pv1_lcl); lnucl <- log(input$ch3_pv1_ucl); z <- qnorm(1 - (1 - input$ch3_pv1_ci/100)/2); se <- (lnucl - lnlcl) / (2 * z); b <- (lnlcl + lnucl) / 2; or_val <- exp(b); wald <- (b / se)^2; p_val <- 1 - pchisq(wald, 1); datatable(data.frame(Estimates=c("OR", "Wald X2", "p"), Value=c(fmt(or_val), fmt(wald), fmt(p_val))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_pv2_table_calc <- renderDT({ est <- log(input$ch3_pv2_or); l <- log(input$ch3_pv2_lcl); u <- log(input$ch3_pv2_ucl); se <- (u - l) / (2 * 1.96); datatable(data.frame(Metric=c("Est", "L", "U", "SE"), Value=c(fmt(est), fmt(l), fmt(u), fmt(se))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_pv2_table_est <- renderDT({ est <- log(input$ch3_pv2_or); l <- log(input$ch3_pv2_lcl); u <- log(input$ch3_pv2_ucl); se <- (u - l) / (2 * 1.96); z <- abs(est / se); p_val <- 2 * (1 - pnorm(z)); datatable(data.frame(Estimates=c("z", "p"), Value=c(fmt(z), fmt(p_val))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_conv_table_or2rr <- renderDT({ p0 <- input$ch3_conv_prev / 100; rr <- input$ch3_conv_or / ((1 - p0) + (input$ch3_conv_or * p0)); lcl <- input$ch3_conv_or_lcl / ((1 - p0) + (input$ch3_conv_or_lcl * p0)); ucl <- input$ch3_conv_or_ucl / ((1 - p0) + (input$ch3_conv_or_ucl * p0)); datatable(data.frame(Estimates=c("RR", "LCL", "UCL"), Value=c(fmt(rr), fmt(lcl), fmt(ucl))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch3_conv_table_rr2or <- renderDT({ p0 <- input$ch3_conv_prev / 100; or_val <- (input$ch3_conv_rr * (1 - p0)) / (1 - input$ch3_conv_rr * p0); lcl <- (input$ch3_conv_rr_lcl * (1 - p0)) / (1 - input$ch3_conv_rr_lcl * p0); ucl <- (input$ch3_conv_rr_ucl * (1 - p0)) / (1 - input$ch3_conv_rr_ucl * p0); datatable(data.frame(Estimates=c("OR", "LCL", "UCL"), Value=c(fmt(or_val), fmt(lcl), fmt(ucl))), options=list(dom='t', ordering=F), rownames=F) })
  
