  ch41_parse <- function(text_input) { cleaned_text <- gsub("[,\\n]", " ", text_input); split_text <- unlist(strsplit(trimws(cleaned_text), "\\s+")); vals <- as.numeric(split_text); vals[!is.na(vals)] }
  ch41_data_tab1 <- reactive({ x <- ch41_parse(input$ch41_tab1_x); f <- ch41_parse(input$ch41_tab1_f); if (length(x) == 0 || length(x) != length(f)) return(NULL); p_x <- f / sum(f); x2 <- x^2; x_px <- x * p_x; x2_px <- x2 * p_x; mean_val <- sum(x_px); var_val <- sum(x2_px) - (mean_val^2); list(x=x, f=f, p_x=p_x, x2=x2, x_px=x_px, x2_px=x2_px, mean=mean_val, var=var_val, sd=sqrt(var_val)) })
  output$ch41_tab1_table <- renderDT({ res <- ch41_data_tab1(); if (is.null(res)) return(datatable(data.frame(Error="Lengths of x and frequencies must match and be numeric."))); df <- data.frame(x=as.character(res$x), Input=fmt(res$f), p_x=fmt(res$p_x), x2=as.character(res$x2), x_px=fmt(res$x_px), x2_px=fmt(res$x2_px)); colnames(df) <- c("Value or Class Midpoint (x)", "Frequency or Probability", "p(x)", "x^2", "x*p(x)", "x^2*p(x)"); sum_row <- data.frame(`Value or Class Midpoint (x)`="Sum", `Frequency or Probability`=fmt(sum(res$f)), `p(x)`=fmt(sum(res$p_x)), `x^2`="", `x*p(x)`=fmt(sum(res$x_px)), `x^2*p(x)`=fmt(sum(res$x2_px)), check.names=F); datatable(rbind(df, sum_row), options=list(dom='t', ordering=F, pageLength=-1), rownames=F) })
  output$ch41_tab1_stats <- renderDT({ res <- ch41_data_tab1(); if(is.null(res)) return(NULL); datatable(data.frame(Statistic=c("Mean", "Variance", "SD"), Value=c(fmt(res$mean), fmt(res$var), fmt(res$sd))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch41_tab1_plot <- renderPlot({ res <- ch41_data_tab1(); if(is.null(res)) return(NULL); ggplot(data.frame(x=factor(res$x, levels=res$x), p_x=res$p_x), aes(x=x, y=p_x)) + geom_bar(stat="identity", fill="lightgray", color="black", width=0.5) + theme_minimal() + labs(title="Probability Density Function", x="x", y="p(x)") + theme(plot.title=element_text(hjust=0.5, face="bold")) })
  ch41_data_tab2 <- reactive({ x <- ch41_parse(input$ch41_tab2_x); w <- ch41_parse(input$ch41_tab2_w); if (length(x) == 0 || length(x) != length(w)) return(NULL); n <- length(x); sum_w <- sum(w); x_w <- x * w; mean_val <- sum(x_w) / sum_w; w_x_mean2 <- w * (x - mean_val)^2; var_val <- if(n>1 && sum_w>0) (sum(w_x_mean2) / sum_w) * (n / (n - 1)) else NA; list(x=x, w=w, x_w=x_w, w_x_mean2=w_x_mean2, n=n, mean=mean_val, var=var_val, sd=sqrt(var_val)) })
  output$ch41_tab2_table <- renderDT({ res <- ch41_data_tab2(); if (is.null(res)) return(datatable(data.frame(Error="Lengths of Value and Weight must match and be numeric."))); df <- data.frame(Value=as.character(res$x), Weight=as.character(res$w), xw=fmt(res$x_w), wxmean2=fmt(res$w_x_mean2)); colnames(df) <- c("Value", "Weight", "x(w)", "w(x-mean)^2"); sum_row <- data.frame(Value="Sum", Weight=as.character(sum(res$w)), `x(w)`=fmt(sum(res$x_w)), `w(x-mean)^2`=fmt(sum(res$w_x_mean2)), check.names=F); count_row <- data.frame(Value="Count", Weight=as.character(res$n), `x(w)`="", `w(x-mean)^2`="", check.names=F); datatable(rbind(df, sum_row, count_row), options=list(dom='t', ordering=F, pageLength=-1), rownames=F) })
  output$ch41_tab2_stats <- renderDT({ res <- ch41_data_tab2(); if(is.null(res)) return(NULL); datatable(data.frame(Statistic=c("Mean", "Variance", "SD"), Value=c(fmt(res$mean), fmt(res$var), fmt(res$sd))), options=list(dom='t', ordering=F), rownames=F) })
  
  output$ch42_bin_prob_table <- renderDT({ req(input$ch42_bin_n1, input$ch42_bin_p1, input$ch42_bin_x1); x <- input$ch42_bin_x1; n <- input$ch42_bin_n1; p <- input$ch42_bin_p1; datatable(data.frame(Result=c("\"=\"", "\"<\"", "\"≤\"", "\">\"", "\"≥\""), Prob=c(fmt(dbinom(x,n,p)), fmt(pbinom(x-1,n,p)), fmt(pbinom(x,n,p)), fmt(1-pbinom(x,n,p)), fmt(1-pbinom(x-1,n,p)))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_bin_between_table <- renderDT({ req(input$ch42_bin_n2, input$ch42_bin_p2, input$ch42_bin_xl, input$ch42_bin_xu); n <- input$ch42_bin_n2; p <- input$ch42_bin_p2; xL <- input$ch42_bin_xl; xU <- input$ch42_bin_xu; datatable(data.frame(Result=c("\"(xL < x < xU)\"", "\"(xL ≤ x < xU)\"", "\"(xL < x ≤ xU)\"", "\"(xL ≤ x ≤ xU)\""), Prob=c(fmt(max(0, pbinom(xU-1,n,p)-pbinom(xL,n,p))), fmt(max(0, pbinom(xU-1,n,p)-pbinom(xL-1,n,p))), fmt(max(0, pbinom(xU,n,p)-pbinom(xL,n,p))), fmt(max(0, pbinom(xU,n,p)-pbinom(xL-1,n,p))))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_bin_q_val <- renderText({ fmt(1 - input$ch42_bin_p3) })
  output$ch42_bin_stats_table <- renderDT({ req(input$ch42_bin_n3, input$ch42_bin_p3); n <- input$ch42_bin_n3; p <- input$ch42_bin_p3; datatable(data.frame(Statistic=c("Mean", "Variance", "SD"), Value=c(fmt(n*p), fmt(n*p*(1-p)), fmt(sqrt(n*p*(1-p))))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_poi_prob_table <- renderDT({ req(input$ch42_poi_mean1, input$ch42_poi_x1); lam <- input$ch42_poi_mean1; x <- input$ch42_poi_x1; datatable(data.frame(Result=c("\"=\"", "\"<\"", "\"≤\"", "\">\"", "\"≥\""), Prob=c(fmt(dpois(x,lam)), fmt(ppois(x-1,lam)), fmt(ppois(x,lam)), fmt(1-ppois(x,lam)), fmt(1-ppois(x-1,lam)))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_poi_between_table <- renderDT({ req(input$ch42_poi_mean2, input$ch42_poi_xl, input$ch42_poi_xu); lam <- input$ch42_poi_mean2; xL <- input$ch42_poi_xl; xU <- input$ch42_poi_xu; datatable(data.frame(Result=c("\"(xL < x < xU)\"", "\"(xL ≤ x < xU)\"", "\"(xL < x ≤ xU)\"", "\"(xL ≤ x ≤ xU)\""), Prob=c(fmt(max(0, ppois(xU-1,lam)-ppois(xL,lam))), fmt(max(0, ppois(xU-1,lam)-ppois(xL-1,lam))), fmt(max(0, ppois(xU,lam)-ppois(xL,lam))), fmt(max(0, ppois(xU,lam)-ppois(xL-1,lam))))), options=list(dom='t', ordering=F), rownames=F) })
  output$ch42_poi_stats_table <- renderDT({ req(input$ch42_poi_num, input$ch42_poi_den); m <- input$ch42_poi_num / input$ch42_poi_den; datatable(data.frame(Statistic=c("Mean", "Variance", "SD"), Value=c(fmt(m), fmt(m), fmt(sqrt(m)))), options=list(dom='t', ordering=F), rownames=F) })
  
  observeEvent(input$ch43_norm_sd, { req(input$ch43_norm_sd); updateNumericInput(session, "ch43_norm_var", value = input$ch43_norm_sd^2) })
