  ch61_d2m_t_neq_data <- reactive({ v1 <- ch61_get_var(input$ch61_d2m_sd_var1, input$ch61_d2m_val1); v2 <- ch61_get_var(input$ch61_d2m_sd_var2, input$ch61_d2m_val2); n1 <- input$ch61_d2m_n1; n2 <- input$ch61_d2m_n2; md <- input$ch61_d2m_mean1 - input$ch61_d2m_mean2; alpha <- 1 - input$ch61_d2m_ci / 100; w1 <- v1 / n1; w2 <- v2 / n2; se <- sqrt(w1 + w2); df1 <- n1 - 1; df2 <- n2 - 1; t1 <- qt(1 - alpha/2, df1); t2 <- qt(1 - alpha/2, df2); t_pool <- (w1*t1 + w2*t2) / (w1 + w2); err_c <- t_pool * se; df_welch_exact <- (w1 + w2)^2 / ( (w1^2)/df1 + (w2^2)/df2 ); df_welch <- floor(df_welch_exact); err_w <- qt(1 - alpha/2, df_welch) * se; list(md=md, df1=df1, df2=df2, t1=t1, t2=t2, t_pool=t_pool, df_welch=df_welch_exact, t_welch=qt(1-alpha/2,df_welch), err_c=err_c, err_w=err_w) })
