  output$ch61_sp2_result_table <- renderTable({ x <- input$ch61_sp2_x; n <- input$ch61_sp2_n; z <- qnorm(1 - (1 - input$ch61_sp2_ci / 100)/2); p <- x / n; err_w <- z * sqrt(p*(1-p)/n); denom <- 1 + z^2/n; center <- (p + z^2/(2*n)) / denom; err_wilson <- (z / denom) * sqrt(p*(1-p)/n + z^2/(4*n^2)); pl <- max(0, p - 1/(2*n)); pu <- min(1, p + 1/(2*n)); wilson_cc_L <- if(x==0) 0 else (pl + z^2/(2*n) - z*sqrt(pl*(1-pl)/n + z^2/(4*n^2))) / denom; wilson_cc_U <- if(x==n) 1 else (pu + z^2/(2*n) + z*sqrt(pu*(1-pu)/n + z^2/(4*n^2))) / denom; n_tilde <- n + z^2; p_tilde <- (x + z^2/2) / n_tilde; err_ac <- z * sqrt(p_tilde*(1-p_tilde)/n_tilde); ex_L <- if(x==0) 0 else qbeta((1 - input$ch61_sp2_ci/100)/2, x, n - x + 1); ex_U <- if(x==n) 1 else qbeta(1 - (1 - input$ch61_sp2_ci/100)/2, x + 1, n - x); jf_L <- if(x==0) 0 else qbeta((1 - input$ch61_sp2_ci/100)/2, x + 0.5, n - x + 0.5); jf_U <- if(x==n) 1 else qbeta(1 - (1 - input$ch61_sp2_ci/100)/2, x + 0.5, n - x + 0.5); asin_L <- sin(max(0, asin(sqrt(p)) - z/(2*sqrt(n))))^2; asin_U <- sin(min(pi/2, asin(sqrt(p)) + z/(2*sqrt(n))))^2; rot0_L <- if(p==0) 0 else NA; rot0_U <- if(p==0) 3/n else NA; rot1_L <- if(p==1) 1 - 3/n else NA; rot1_U <- if(p==1) 1 else NA; data.frame(Type=c("Wald (Normal)", "Wilson", "Wilson CC", "Agresti-Coull", "Exact", "Jeffries", "Arcsine UC", "RoT (IF p=0)", "RoT (IF p=1)"), LCL=fmt(c(p - err_w, center - err_wilson, wilson_cc_L, p_tilde - err_ac, ex_L, jf_L, asin_L, rot0_L, rot1_L)), UCL=fmt(c(p + err_w, center + err_wilson, wilson_cc_U, p_tilde + err_ac, ex_U, jf_U, asin_U, rot0_U, rot1_U))) })
