  ch9_corr_ci_res <- reactive({ req(input$ch9_r_val, input$ch9_n_val, input$ch9_ci_corr); r <- input$ch9_r_val; n <- input$ch9_n_val; conf <- input$ch9_ci_corr / 100; z_r <- 0.5 * log((1 + r) / (1 - r)); se <- 1 / sqrt(n - 3); z_crit <- qnorm(1 - (1 - conf) / 2); ll_z <- z_r - z_crit * se; ul_z <- z_r + z_crit * se; data.frame(Metric=c("z(r)", "LL (Z)", "UL (Z)", "LCL (r)", "UCL (r)"), Value=c(z_r, ll_z, ul_z, tanh(ll_z), tanh(ul_z))) })
