  ch114_raw_data <- reactive({ df <- NULL; if(input$ch114_input_type == "paste") { req(input$ch114_pasted_data != ""); tryCatch({ df <- read.table(text = input$ch114_pasted_data, header = TRUE, sep = "\t", stringsAsFactors = FALSE); if(ncol(df) == 1) df <- read.csv(text = input$ch114_pasted_data, header = TRUE, stringsAsFactors = FALSE) }, error=function(e){NULL}) } else { req(input$ch114_file_data); ext <- tools::file_ext(input$ch114_file_data$name); tryCatch({ if(ext=="csv") df <- read.csv(input$ch114_file_data$datapath, stringsAsFactors=FALSE) else if(ext %in% c("xls","xlsx")) df <- as.data.frame(readxl::read_excel(input$ch114_file_data$datapath)) }, error=function(e){NULL}) }; return(df) })
