  output$ch114_dv_event_selector <- renderUI({ df <- ch114_raw_data(); req(df, input$ch114_var_DV); lvls <- unique(na.omit(df[[input$ch114_var_DV]])); if(length(lvls)<2) return(helpText("DV must have at least 2 unique levels.")); selectInput("ch114_dv_event", "Event of Interest (Target = 1):", choices=lvls, selected=lvls[1]) })
  output$ch114_cat_var_selector <- renderUI({ req(input$ch114_var_IV); selectInput("ch114_var_IV_cat", "Select Categorical Independent Variables:", choices=input$ch114_var_IV, multiple=TRUE) })
  output$ch114_ref_level_selectors <- renderUI({ req(input$ch114_var_IV_cat); df <- ch114_raw_data(); req(df); lapply(input$ch114_var_IV_cat, function(col) { lvls <- as.character(unique(na.omit(df[[col]]))); selectInput(paste0("ch114_ref_", col), paste0("Reference Level for ", col, ":"), choices=lvls, selected=lvls[1]) }) })
  output$ch114_interaction_ui <- renderUI({ req(input$ch114_var_IV); if(length(input$ch114_var_IV) < 2) return(helpText("Select >= 2 IVs to create interactions.")); pairs <- combn(input$ch114_var_IV, 2); pair_names <- apply(pairs, 2, paste, collapse=":"); checkboxGroupInput("ch114_int_terms", "Select 2-Way Interactions:", choices=pair_names) })
  ch114_proc_data <- reactive({ df <- ch114_raw_data(); req(df, input$ch114_var_DV, input$ch114_dv_event, length(input$ch114_var_IV)>0); if(!is.null(input$ch114_var_freq) && input$ch114_var_freq != "") { freq_col <- input$ch114_var_freq; req(freq_col %in% names(df)); freqs <- round(as.numeric(df[[freq_col]])); freqs[is.na(freqs)] <- 0; df <- df[rep(seq_len(nrow(df)), freqs), ] }; selected_cols <- c(input$ch114_var_DV, input$ch114_var_IV); if(!all(selected_cols %in% names(df))) return(NULL); df <- df[complete.cases(df[, selected_cols]), ]; req(nrow(df)>0); df[["Y_MODEL"]] <- ifelse(as.character(df[[input$ch114_var_DV]]) == as.character(input$ch114_dv_event), 1, 0); cat_vars <- if(is.null(input$ch114_var_IV_cat)) character(0) else input$ch114_var_IV_cat; for(col in input$ch114_var_IV) { if(col %in% cat_vars) { ref_val <- input[[paste0("ch114_ref_", col)]]; if(!is.null(ref_val)) df[[col]] <- relevel(factor(as.character(df[[col]])), ref=as.character(ref_val)) else df[[col]] <- as.factor(df[[col]]) } else { df[[col]] <- as.numeric(df[[col]]) } }; return(df) })
  ch114_model_obj <- reactive({ df <- ch114_proc_data(); req(df); f_str <- paste("Y_MODEL ~", paste0("`", input$ch114_var_IV, "`", collapse=" + ")); if(input$ch114_add_interaction && length(input$ch114_int_terms)>0) { int_fmt <- sapply(input$ch114_int_terms, function(x){ vars <- strsplit(x, ":")[[1]]; paste0("`", vars[1], "`:`", vars[2], "`") }); f_str <- paste(f_str, "+", paste(int_fmt, collapse=" + ")) }; glm(as.formula(f_str), data=df, family=binomial(link="logit")) })
  output$ch114_resp_profile <- renderDT({ df <- ch114_proc_data(); req(df); tbl <- table(df[[input$ch114_var_DV]]); res_df <- data.frame(Outcome=names(tbl), Frequency=as.integer(tbl)); res_df <- res_df[order(res_df$Outcome == as.character(input$ch114_dv_event), decreasing=TRUE), ]; datatable(res_df, options=dt_opts, rownames=FALSE) })
  output$ch114_data_preview <- renderDT({ req(ch114_proc_data()); datatable(head(ch114_proc_data(), 50), options=list(pageLength=10, dom='tip', className='dt-center'), rownames=FALSE) })
  output$ch114_model_status <- renderUI({ mod <- ch114_model_obj(); req(mod); conv_txt <- ifelse(mod$converged, "<span style='color:green;'>Model Converged successfully.</span>", "<span style='color:red;'>Model DID NOT Converge.</span>"); se <- summary(mod)$coefficients[, 2]; fitted_p <- fitted(mod); sep_txt <- "<span style='color:green;'>No obvious quasi or semi-quasi separation detected.</span>"; if(any(se > 20) || any(fitted_p < 1e-5) || any(fitted_p > 1 - 1e-5)) sep_txt <- "<span style='color:red;'>Warning: Possible quasi-complete or complete separation detected.</span>"; HTML(paste(conv_txt, sep_txt, sep="<br><br>")) })
  output$ch114_fit_stats <- renderDT({ mod <- ch114_model_obj(); req(mod); n <- length(mod$y); k <- length(coef(mod)); l0 <- mod$null.deviance; aic0 <- l0 + 2; sc0 <- l0 + log(n); l1 <- mod$deviance; aic1 <- mod$aic; sc1 <- l1 + log(n)*k; df <- data.frame(Criterion=c("AIC", "SC (BIC)", "-2 Log L"), `Intercept Only`=c(fmt(aic0), fmt(sc0), fmt(l0)), `Intercept and Covariates`=c(fmt(aic1), fmt(sc1), fmt(l1)), check.names=FALSE); datatable(df, options=dt_opts, rownames=FALSE) })
  output$ch114_global_test <- renderDT({ mod <- ch114_model_obj(); req(mod); lr_stat <- mod$null.deviance - mod$deviance; df <- mod$df.null - mod$df.residual; p_val <- pchisq(lr_stat, df, lower.tail=FALSE); res_df <- data.frame(Test="Likelihood Ratio", `Chi-Square`=fmt(lr_stat), DF=df, `Pr > ChiSq`=p_fmt(p_val), check.names=FALSE); datatable(res_df, options=dt_opts, rownames=FALSE) })
  output$ch114_type3_table <- renderDT({ mod <- ch114_model_obj(); req(mod); tryCatch({ t3 <- car::Anova(mod, type="III", test.statistic="Wald"); res_df <- data.frame(Effect=rownames(t3), DF=t3$Df, `Wald Chi-Square`=fmt(t3$Chisq), `Pr > ChiSq`=p_fmt(t3$`Pr(>Chisq)`), check.names=FALSE); res_df <- res_df[res_df$Effect != "(Intercept)", ] }, error=function(e){ res_df <- data.frame(Error="Could not compute Type 3 tests.") }); datatable(res_df, options=dt_opts, rownames=FALSE) })
  output$ch114_param_table <- renderDT({ mod <- ch114_model_obj(); req(mod); coefs <- summary(mod)$coefficients; wald_chi <- (coefs[,1]/coefs[,2])^2; res_df <- data.frame(Parameter=gsub("`", "", rownames(coefs)), DF=1, Estimate=fmt(coefs[,1]), `Standard Error`=fmt(coefs[,2]), `Wald Chi-Square`=fmt(wald_chi), `Pr > ChiSq`=p_fmt(coefs[,4]), check.names=FALSE); datatable(res_df, options=dt_opts, rownames=FALSE) })
  output$ch114_or_table <- renderDT({ mod <- ch114_model_obj(); req(mod); est <- coef(mod); ci <- suppressMessages(confint.default(mod)); or <- exp(est); or_l <- exp(ci[,1]); or_u <- exp(ci[,2]); res_df <- data.frame(Effect=gsub("`", "", rownames(ci)), `Point Estimate`=fmt(or), `95% Wald CI Lower`=fmt(or_l), `95% Wald CI Upper`=fmt(or_u), check.names=FALSE); res_df <- res_df[res_df$Effect != "(Intercept)", ]; datatable(res_df, options=dt_opts, rownames=FALSE) })
  output$ch114_roc_plot <- renderPlot({ mod <- ch114_model_obj(); req(mod); df <- ch114_proc_data(); req(df); roc_obj <- roc(df$Y_MODEL, fitted(mod), quiet=TRUE); plot(roc_obj, main="ROC Curve", col="steelblue", lwd=2); legend("bottomright", legend=sprintf("AUC = %.4f", auc(roc_obj)), bty="n", cex=1.2, text.col="red", text.font=2) })
  output$ch114_forest_plot <- renderPlot({ mod <- ch114_model_obj(); req(mod); est <- coef(mod); ci <- suppressMessages(confint.default(mod)); df_plot <- data.frame(Term=gsub("`", "", rownames(ci)), OR=exp(est), LCL=exp(ci[,1]), UCL=exp(ci[,2])); df_plot <- df_plot[df_plot$Term != "(Intercept)", ]; req(nrow(df_plot)>0); ggplot(df_plot, aes(x=OR, y=reorder(Term, OR))) + geom_point(size=3, color="steelblue") + geom_errorbarh(aes(xmin=LCL, xmax=UCL), height=0.2, color="steelblue") + geom_vline(xintercept=1, linetype="dashed", color="red") + scale_x_log10() + labs(title="Odds Ratios with 95% Wald CI", x="Odds Ratio (Log Scale)", y="Effect") + theme_bw() + theme(plot.title=element_text(hjust=0.5, face="bold")) })
  output$ch114_runs_test_table <- renderDT({ mod <- ch114_model_obj(); req(mod); res <- residuals(mod, type="deviance"); r_test <- runs_test_custom(res); df <- data.frame(Test="Runs Test (Deviance Residuals)", Runs=r_test$runs, Z=fmt(r_test$z), `p-value`=p_fmt(r_test$p), check.names=FALSE); datatable(df, options=dt_opts, rownames=FALSE) })
  output$ch114_bt_status <- renderUI({ df <- ch114_proc_data(); req(df); cat_vars <- input$ch114_var_IV_cat; num_vars <- setdiff(input$ch114_var_IV, cat_vars); if(length(num_vars)==0) return(HTML("<span style='color:gray;'>No continuous independent variables selected. Box-Tidwell test is skipped.</span>")); return(HTML("")) })
  output$ch114_bt_test_table <- renderDT({ df <- ch114_proc_data(); req(df); cat_vars <- input$ch114_var_IV_cat; if(is.null(cat_vars)) cat_vars <- character(0); num_vars <- setdiff(input$ch114_var_IV, cat_vars); req(length(num_vars)>0); df_bt <- df; bt_terms <- c(); for(col in num_vars) { val <- df_bt[[col]]; if(any(val<=0)) val <- val - min(val) + 1e-5; ln_col <- paste0(col, "_ln"); df_bt[[ln_col]] <- val * log(val); bt_terms <- c(bt_terms, ln_col) }; f_str <- paste("Y_MODEL ~", paste0("`", input$ch114_var_IV, "`", collapse=" + "), "+", paste0("`", bt_terms, "`", collapse=" + ")); bt_mod <- glm(as.formula(f_str), data=df_bt, family=binomial(link="logit")); coefs <- summary(bt_mod)$coefficients; res_df <- data.frame(Continuous_Variable=character(), Estimate=character(), `Pr > ChiSq`=character(), check.names=FALSE); for(i in 1:length(num_vars)) { term <- bt_terms[i]; orig_term <- num_vars[i]; idx <- grep(paste0("^`?", term, "`?$"), rownames(coefs)); if(length(idx)>0) { res_df <- rbind(res_df, data.frame(`Continuous Variable`=orig_term, `Interaction Term`=paste0(orig_term, " * ln(", orig_term, ")"), Estimate=fmt(coefs[idx,1]), `Pr > ChiSq`=p_fmt(coefs[idx,4]), check.names=FALSE)) } }; datatable(res_df, options=dt_opts, rownames=FALSE) })
  
  # ==========================================
  # CHAPTER 12
  # ==========================================
  ch12_data_matrix <- reactive({
    mat <- NULL
    if (input$ch12_input_type == "paste") {
      req(input$ch12_pasted_data != "")
      vals <- as.numeric(unlist(strsplit(trimws(input$ch12_pasted_data), "[,\\s\\n]+", perl = TRUE)))
      vals <- vals[!is.na(vals)]
      req(length(vals) > 0); req(input$ch12_num_rows > 0, input$ch12_num_cols > 0)
      expected_len <- input$ch12_num_rows * input$ch12_num_cols
      if (length(vals) < expected_len) { vals <- c(vals, rep(NA, expected_len - length(vals))) }
      mat <- matrix(vals[1:expected_len], nrow = input$ch12_num_rows, ncol = input$ch12_num_cols, byrow = TRUE)
    } else {
      req(input$ch12_file_data)
      ext <- tools::file_ext(input$ch12_file_data$name)
      tryCatch({
        df <- if(ext == "csv") { read.csv(input$ch12_file_data$datapath, header = FALSE, stringsAsFactors = FALSE) } else { as.data.frame(readxl::read_excel(input$ch12_file_data$datapath, col_names = FALSE)) }
        if (input$ch12_has_header) { df <- df[-1, -1, drop = FALSE] }
        mat <- as.matrix(df)
        suppressWarnings(mode(mat) <- "numeric")
        mat <- mat[!apply(is.na(mat), 1, all), !apply(is.na(mat), 2, all), drop = FALSE]
      }, error = function(e) { mat <- NULL })
    }
    return(mat)
  })
  
  output$ch12_data_preview <- renderDT({ mat <- ch12_data_matrix(); req(mat); df <- as.data.frame(mat); colnames(df) <- paste("Col", 1:ncol(df)); rownames(df) <- paste("Row", 1:nrow(df)); datatable(df, options = dt_opts, rownames = TRUE) })
  
  ch12_gof_calc <- reactive({
    mat <- ch12_data_matrix(); req(mat); obs <- as.vector(t(mat)); obs <- obs[!is.na(obs)]; validate(need(length(obs) > 1, "Goodness-of-Fit requires at least 2 categories."))
    k <- length(obs); n <- sum(obs)
    if (input$ch12_gof_dist == "Uniform") { probs <- rep(1/k, k) } else { probs <- as.numeric(unlist(strsplit(trimws(input$ch12_gof_probs), "[,\\s\\n]+", perl = TRUE))); probs <- probs[!is.na(probs)]; validate(need(length(probs) == k, "Number of probabilities must match number of observed categories.")) }
    exp <- n * probs; chi_cell <- ((obs - exp)^2) / exp; chi_sq <- sum(chi_cell); df <- k - 1; p_val <- 1 - pchisq(chi_sq, df)
    adj_res <- (obs - exp) / sqrt(n * probs * (1 - probs)); p_adj <- 2 * (1 - pnorm(abs(adj_res))); bon_sig <- ifelse(p_adj < (0.05 / k), "sig", "n.s."); cramer_v <- sqrt(chi_sq / (n * (k - 1)))
    list(obs = obs, probs = probs, exp = exp, chi_cell = chi_cell, adj_res = adj_res, bon_sig = bon_sig, chi_sq = chi_sq, df = df, p_val = p_val, cramer_v = cramer_v, n = n, k = k)
  })
  output$ch12_gof_table <- renderDT({ res <- ch12_gof_calc(); df <- data.frame(Category = 1:res$k, Observed = res$obs, Expected = fmt(res$exp), `((O-E)^2)/E` = fmt(res$chi_cell), `Adj. Stand. Resid.` = fmt(res$adj_res), `Bon Adj. (alpha = 0.05)` = res$bon_sig, check.names = FALSE)
  if (input$ch12_gof_dist == "User-Specified") { df <- data.frame(Category = 1:res$k, Observed = res$obs, Probability = fmt(res$probs), Expected = fmt(res$exp), `((O-E)^2)/E` = fmt(res$chi_cell), `Adj. Stand. Resid.` = fmt(res$adj_res), `Bon Adj. (alpha = 0.05)` = res$bon_sig, check.names = FALSE) }
  totals <- df[1, ]; totals[1, ] <- NA; totals$Category <- "TOTALS"; totals$Observed <- sum(res$obs); totals$Expected <- fmt(sum(res$exp)); totals$`((O-E)^2)/E` <- fmt(res$chi_sq)
  if(input$ch12_gof_dist == "User-Specified") { totals$Probability <- 1 }; datatable(rbind(df, totals), options = dt_opts, rownames = FALSE) })
  output$ch12_gof_summary <- renderDT({ res <- ch12_gof_calc(); df <- data.frame(Metric = c("Chi-square", "d.f.", "Prob.", "p-value"), Value = c(fmt(res$chi_sq), res$df, fmt(res$p_val), p_fmt(res$p_val))); datatable(df, options = list(dom = 't', ordering = FALSE, headerCallback = JS("function(thead) {$(thead).remove();}")), rownames = FALSE) })
  output$ch12_gof_es <- renderDT({ res <- ch12_gof_calc(); w <- res$cramer_v * sqrt(res$k - 1); df <- data.frame(ES = "Cramer's V", Value = fmt(res$cramer_v), Size = get_es_size(w)); datatable(df, options = dt_opts, rownames = FALSE) })
  
  ch12_get_2x2 <- reactive({ mat <- ch12_data_matrix(); req(mat); validate(need(nrow(mat) == 2 && ncol(mat) == 2, "This test requires a 2x2 table.")); mat })
  ch12_mc_calc <- reactive({ mat <- ch12_get_2x2(); a <- mat[1,1]; b <- mat[1,2]; c <- mat[2,1]; d <- mat[2,2]; n <- a + b + c + d; chi_sq <- ((abs(b - c) - 1)^2) / (b + c); p_val <- 1 - pchisq(chi_sq, 1); phi <- sqrt(chi_sq / n); list(a=a, b=b, c=c, d=d, n=n, chi_sq=chi_sq, p_val=p_val, phi=phi) })
  output$ch12_mc_table <- renderDT({ res <- ch12_mc_calc(); df <- data.frame(` ` = c("Time 1: Category 1", "Time 1: Category 2", "TOTAL"), `Time 2: Category 1` = c(res$a, res$c, res$a + res$c), `Time 2: Category 2` = c(res$b, res$d, res$b + res$d), TOTAL = c(res$a + res$b, res$c + res$d, res$n), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$ch12_mc_summary <- renderDT({ res <- ch12_mc_calc(); df <- data.frame(Metric = c("McNemar's Chi-square", "Prob.", "p-value"), Value = c(fmt(res$chi_sq), fmt(res$p_val), p_fmt(res$p_val))); datatable(df, options = list(dom = 't', ordering = FALSE, headerCallback = JS("function(thead) {$(thead).remove();}")), rownames = FALSE) })
  output$ch12_mc_es <- renderDT({ res <- ch12_mc_calc(); df <- data.frame(ES = c("Phi Coefficient", "Cramer's V"), Value = c(fmt(res$phi), fmt(res$phi)), Size = c(get_es_size(res$phi), get_es_size(res$phi))); datatable(df, options = dt_opts, rownames = FALSE) })
  
  ch12_fy_calc <- reactive({ mat <- ch12_get_2x2(); a <- mat[1,1]; b <- mat[1,2]; c <- mat[2,1]; d <- mat[2,2]; n <- sum(mat); y_test <- suppressWarnings(chisq.test(mat, correct = TRUE)); y_chi <- y_test$statistic; y_pval <- y_test$p.value; y_phi <- sqrt(y_chi / n); p_neq <- fisher.test(mat, alternative = "two.sided")$p.value; p_less <- fisher.test(mat, alternative = "less")$p.value; p_greater <- fisher.test(mat, alternative = "greater")$p.value; p_a <- dhyper(a, a+b, c+d, a+c); odds <- (a * d) / (b * c); list(a=a, b=b, c=c, d=d, n=n, mat=mat, y_chi=y_chi, y_pval=y_pval, y_phi=y_phi, p_neq=p_neq, p_less=p_less, p_greater=p_greater, p_a=p_a, odds=odds) })
  output$ch12_fy_table <- renderDT({ res <- ch12_fy_calc(); df <- data.frame(` ` = c("Row 1", "Row 2", "TOTAL"), `Column 1` = c(res$a, res$c, res$a + res$c), `Column 2` = c(res$b, res$d, res$b + res$d), TOTAL = c(res$a + res$b, res$c + res$d, res$n), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$ch12_fisher_working <- renderDT({ res <- ch12_fy_calc(); df <- data.frame(Metric = c("a", "a+b", "a+c", "n", "P(a)"), Value = c(res$a, res$a+res$b, res$a+res$c, res$n, fmt(res$p_a))); datatable(df, options = list(dom = 't', ordering = FALSE, headerCallback = JS("function(thead) {$(thead).remove();}")), rownames = FALSE) })
