  ch12_rxc_calc <- reactive({ mat <- ch12_data_matrix(); req(mat); validate(need(nrow(mat) >= 2 && ncol(mat) >= 2, "RxC Test requires at least a 2x2 matrix.")); n <- sum(mat); r <- nrow(mat); c <- ncol(mat); row_sums <- rowSums(mat); col_sums <- colSums(mat); exp <- outer(row_sums, col_sums) / n; p_chi_cell <- (mat - exp)^2 / exp; p_chi <- sum(p_chi_cell); df <- (r - 1) * (c - 1); p_pval <- 1 - pchisq(p_chi, df); lr_cell <- ifelse(mat > 0, mat * log(mat / exp), 0); lr_chi <- 2 * sum(lr_cell); lr_pval <- 1 - pchisq(lr_chi, df); df_star <- min(r - 1, c - 1); p_phi <- sqrt(p_chi / n); p_cramer <- sqrt(p_chi / (n * df_star)); lr_phi <- sqrt(lr_chi / n); lr_cramer <- sqrt(lr_chi / (n * df_star)); list(mat=mat, exp=exp, p_chi_cell=p_chi_cell, p_chi=p_chi, p_pval=p_pval, lr_cell=lr_cell, lr_chi=lr_chi, lr_pval=lr_pval, df=df, p_phi=p_phi, p_cramer=p_cramer, lr_phi=lr_phi, lr_cramer=lr_cramer, df_star=df_star) })
  ch12_append_margins <- function(mat) { df <- as.data.frame(mat); df$TOTAL <- rowSums(mat); tot_row <- c(colSums(mat), sum(mat)); df <- rbind(df, tot_row); df <- cbind(Row = c(1:nrow(mat), "TOTAL"), df); return(df) }
  output$ch12_rxc_obs <- renderDT({ res <- ch12_rxc_calc(); df <- ch12_append_margins(res$mat); colnames(df)[2:(ncol(df)-1)] <- 1:ncol(res$mat); datatable(df, options = dt_opts, rownames = FALSE) })
