  output$ch12_rxc_lr_cell <- renderDT({ res <- ch12_rxc_calc(); df <- ch12_append_margins(res$lr_cell); df[, 2:ncol(df)] <- apply(df[, 2:ncol(df)], c(1,2), fmt); colnames(df)[2:(ncol(df)-1)] <- 1:ncol(res$mat); datatable(df, options = dt_opts, rownames = FALSE) })
  output$ch12_rxc_lr_sum <- renderDT({ res <- ch12_rxc_calc(); df <- data.frame(Metric = c("LR Chi-square", "d.f.", "Prob.", "p-value"), Value = c(fmt(res$lr_chi), res$df, fmt(res$lr_pval), p_fmt(res$lr_pval))); datatable(df, options = list(dom = 't', ordering = FALSE, headerCallback = JS("function(thead) {$(thead).remove();}")), rownames = FALSE) })
