  output$out_d1_ci_z <- renderDT({ z_val <- qnorm(1 - (1 - input$d1_ci_conf)/2); datatable(data.frame(Metric = "z", Value = fmt(z_val)), options = dt_opts_nohead, rownames = FALSE) })
  output$out_d1_ci_res <- renderDT({ z_val <- qnorm(1 - (1 - input$d1_ci_conf)/2); calc <- (z_val / input$d1_ci_err)^2 * input$d1_ci_p * (1 - input$d1_ci_p); df <- data.frame(` ` = "n", calculated = fmt(calc), final = ceiling(calc), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d1_t_z <- renderDT({ es <- abs(input$d1_t_p1 - input$d1_t_p0) / input$d1_t_sd; z_a_1 <- qnorm(1 - input$d1_t_alpha); z_a_2 <- qnorm(1 - input$d1_t_alpha/2); z_b_1 <- qnorm(min(0.999999, input$d1_t_power)); z_b_2 <- qnorm(min(0.999999, input$d1_t_power + input$d1_t_alpha/2)); df <- data.frame(Metric = c("ES", "z(alpha)", "z(beta)"), `1-sided` = c(fmt(es), fmt(z_a_1), fmt(z_b_1)), `2-sided` = c(fmt(es), fmt(z_a_2), fmt(z_b_2)), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d1_t_res <- renderDT({ es <- abs(input$d1_t_p1 - input$d1_t_p0) / input$d1_t_sd; z_a_1 <- qnorm(1 - input$d1_t_alpha); z_a_2 <- qnorm(1 - input$d1_t_alpha/2); z_b_1 <- qnorm(min(0.999999, input$d1_t_power)); z_b_2 <- qnorm(min(0.999999, input$d1_t_power + input$d1_t_alpha/2)); n_1 <- ((z_a_1 + z_b_1) / es)^2; n_2 <- ((z_a_2 + z_b_2) / es)^2; df <- data.frame(n = c("1-sided", "2-sided"), calculated = c(fmt(n_1), fmt(n_2)), final = c(ceiling(n_1), ceiling(n_2))); datatable(df, options = dt_opts, rownames = FALSE) })
