  output$out_d2_ci1_res <- renderDT({ z_val <- qnorm(1 - (1 - input$d2_ci1_conf)/2); p1 <- input$d2_ci1_p1; p2 <- input$d2_ci1_p2; calc <- 2 * (z_val / input$d2_ci1_err)^2 * ((p1*(1-p1) + p2*(1-p2))/2); df <- data.frame(` ` = c("n 1", "n 2", "Total"), calculated = c(fmt(calc), fmt(calc), fmt(calc*2)), final = c(ceiling(calc), ceiling(calc), ceiling(calc)*2), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d2_ci2_z <- renderDT({ z_val <- qnorm(1 - (1 - input$d2_ci2_conf)/2); p1 <- input$d2_ci2_x1 / input$d2_ci2_n1; p2 <- input$d2_ci2_x2 / input$d2_ci2_n2; datatable(data.frame(Metric = c("z", "p 1", "p 2"), Value = c(fmt(z_val), fmt(p1), fmt(p2))), options = dt_opts_nohead, rownames = FALSE) })
  output$out_d2_ci2_res <- renderDT({ z_val <- qnorm(1 - (1 - input$d2_ci2_conf)/2); p1 <- input$d2_ci2_x1 / input$d2_ci2_n1; p2 <- input$d2_ci2_x2 / input$d2_ci2_n2; calc <- 2 * (z_val / input$d2_ci2_err)^2 * ((p1*(1-p1) + p2*(1-p2))/2); df <- data.frame(` ` = c("n 1", "n 2", "Total"), calculated = c(fmt(calc), fmt(calc), fmt(calc*2)), final = c(ceiling(calc), ceiling(calc), ceiling(calc)*2), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d2_t1_z <- renderDT({ es <- input$d2_t1_diff / sqrt(input$d2_t1_meanp * (1 - input$d2_t1_meanp)); z_a_1 <- qnorm(1 - input$d2_t1_alpha); z_a_2 <- qnorm(1 - input$d2_t1_alpha/2); z_b_1 <- qnorm(min(0.999999, input$d2_t1_power)); z_b_2 <- qnorm(min(0.999999, input$d2_t1_power + input$d2_t1_alpha/2)); df <- data.frame(Metric = c("ES", "z(alpha)", "z(beta)"), `1-sided` = c(fmt(es), fmt(z_a_1), fmt(z_b_1)), `2-sided` = c(fmt(es), fmt(z_a_2), fmt(z_b_2)), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d2_t1_res <- renderDT({ es <- input$d2_t1_diff / sqrt(input$d2_t1_meanp * (1 - input$d2_t1_meanp)); z_a_1 <- qnorm(1 - input$d2_t1_alpha); z_a_2 <- qnorm(1 - input$d2_t1_alpha/2); z_b_1 <- qnorm(min(0.999999, input$d2_t1_power)); z_b_2 <- qnorm(min(0.999999, input$d2_t1_power + input$d2_t1_alpha/2)); n1_1s <- 2 * ((z_a_1 + z_b_1) / es)^2; n1_2s <- 2 * ((z_a_2 + z_b_2) / es)^2; df <- data.frame(n = c("1-sided", "", "", "2-sided", "", ""), split = c("n 1", "n 2", "Total", "n 1", "n 2", "Total"), calculated = c(fmt(n1_1s), fmt(n1_1s), fmt(n1_1s*2), fmt(n1_2s), fmt(n1_2s), fmt(n1_2s*2)), final = c(ceiling(n1_1s), ceiling(n1_1s), ceiling(n1_1s)*2, ceiling(n1_2s), ceiling(n1_2s), ceiling(n1_2s)*2)); datatable(df, options = dt_opts, rownames = FALSE) })
  output$out_d2_t2_z <- renderDT({ p1 <- input$d2_t2_x1 / input$d2_t2_n1; p2 <- input$d2_t2_x2 / input$d2_t2_n2; p_pool <- (input$d2_t2_x1 + input$d2_t2_x2) / (input$d2_t2_n1 + input$d2_t2_n2); es <- abs(p1 - p2) / sqrt(p_pool * (1 - p_pool)); z_a_1 <- qnorm(1 - input$d2_t2_alpha); z_a_2 <- qnorm(1 - input$d2_t2_alpha/2); z_b_1 <- qnorm(min(0.999999, input$d2_t2_power)); z_b_2 <- qnorm(min(0.999999, input$d2_t2_power + input$d2_t2_alpha/2)); df <- data.frame(Metric = c("ES", "z(alpha)", "z(beta)", "p 1", "p 2", "p-pooled"), `1-sided` = c(fmt(es), fmt(z_a_1), fmt(z_b_1), fmt(p1), fmt(p2), fmt(p_pool)), `2-sided` = c(fmt(es), fmt(z_a_2), fmt(z_b_2), fmt(p1), fmt(p2), fmt(p_pool)), check.names = FALSE); datatable(df, options = dt_opts, rownames = FALSE) })
