  output$out_surv_z <- renderDT({ z_val <- qnorm(1 - (1 - input$surv_conf)/2); samp_sz <- z_val^2 * 0.5 * 0.5 / input$surv_err^2; df <- data.frame(Metric = c("z", "SampSize"), Value = c(fmt(z_val), fmt(samp_sz))); datatable(df, options = dt_opts_nohead, rownames = FALSE) })
  output$out_surv_res <- renderDT({ z_val <- qnorm(1 - (1 - input$surv_conf)/2); samp_sz <- z_val^2 * 0.5 * 0.5 / input$surv_err^2; est <- samp_sz / (1 + samp_sz / input$surv_pop); final <- ceiling(est / input$surv_rate); with_100 <- ceiling(est); df <- data.frame(Metric = c("Estimate", "Final", "With 100% Response Rate"), Value = c(fmt(est), final, with_100)); datatable(df, options = list(dom='t', ordering=F, columnDefs=list(list(className='dt-center', targets="_all"))), rownames=FALSE) })
