  output$out_pv_d_res <- renderDT({ z_ci <- qnorm(1 - (1 - input$pv_d_ci/100)/2); se <- (input$pv_d_ucl - input$pv_d_lcl) / (2 * z_ci); z_test <- abs(input$pv_d_est) / se; pval <- 2 * (1 - pnorm(z_test)); df <- data.frame(Metric = c("Reliability Coeff", "SE", "z", "P-value"), Value = c(fmt(z_ci), fmt(se), fmt(z_test), p_fmt(pval))); datatable(df, options = dt_opts_nohead, rownames = FALSE) })
  output$out_pv_r_res <- renderDT({ est_tr <- log(input$pv_r_est); lcl_tr <- log(input$pv_r_lcl); ucl_tr <- log(input$pv_r_ucl); z_ci <- qnorm(1 - (1 - input$pv_r_ci/100)/2); se <- (ucl_tr - lcl_tr) / (2 * z_ci); z_test <- abs(est_tr) / se; pval <- 2 * (1 - pnorm(z_test)); df <- data.frame(Metric = c("Estimate Transform", "LCL Transform", "UCL Transoform", "Reliability Coeff", "SE", "z", "P-value"), Value = c(fmt(est_tr), fmt(lcl_tr), fmt(ucl_tr), fmt(z_ci), fmt(se), fmt(z_test), p_fmt(pval))); datatable(df, options = dt_opts_nohead, rownames = FALSE) })
  
